import{_ as i,a0 as a,w as d,s as c,ao as l,I as p,x as o,a1 as t,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"基礎的Docker容器網絡命令 | LCTT x X-CMD","titleTemplate":false,"description":"基礎的Docker容器網絡命令 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"基礎的Docker容器網絡命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"基礎的Docker容器網絡命令 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150515 Basic Networking Commands with Docker Containers","title":"基礎的Docker容器網絡命令","tag":"201506","desc":""},"relativePath":"201506/20150515 Basic Networking Commands with Docker Containers.md","filePath":"[post].md"}'),s={name:"201506/20150515 Basic Networking Commands with Docker Containers.md"};function k(m,e,g,h,u,b){const r=a("Link");return d(),c("div",null,[e[13]||(e[13]=l(`<h1 id="基礎的docker容器網絡命令" tabindex="-1">基礎的Docker容器網絡命令 <a class="header-anchor" href="#基礎的docker容器網絡命令" aria-label="Permalink to “基礎的Docker容器網絡命令”">​</a></h1><p>各位好，今天我們將學習一些Docker容器的基礎命令。Docker 是一個開源項目，提供了一個可以打包、裝載和運行任何應用的輕量級容器的開放平台。它沒有語言支持、框架和打包系統的限制，從小型的家用電腦到高端服務器，在何時何地都可以運行。它可以使部署和擴展web應用程序、資料庫和後端服務像搭積木一樣容易，而不依賴特定技術棧或提供商。Docker適用於網絡環境，它正應用於數據中心、ISP和越來越多的網絡服務。</p><p>因此，這裏有一些你在管理Docker容器的時候會用到的一些命令。</p><h3 id="_1-找到docker接口" tabindex="-1">1. 找到Docker接口 <a class="header-anchor" href="#_1-找到docker接口" aria-label="Permalink to “1. 找到Docker接口”">​</a></h3><p>Docker默認會創建一個名為docker0的網橋接口作為連接外部世界的基礎。運行中的docker容器直接連接到網橋接口docker0。默認上，docker會分配172.17.42.1/16給docker0，它是所有運行中的容器ip地址的子網。找到Docker接口的ip地址非常簡單。要找出docker0網橋接口和連接到網橋上的docker容器，我們可以在安裝了docker的終端或者shell中運行ip命令。</p><pre><code># ip a
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-interface.png" alt="Docker Interface"></p><h3 id="_2-得到docker容器的ip地址" tabindex="-1">2. 得到Docker容器的ip地址 <a class="header-anchor" href="#_2-得到docker容器的ip地址" aria-label="Permalink to “2. 得到Docker容器的ip地址”">​</a></h3><p>如我們上面讀到的，docker在宿主機中創建了一個叫docker0的網橋接口。在我們創建一個新的docker容器時，它自動被默認分配了一個在該子網範圍內的ip地址。因此，要檢測運行中的Docker容器的ip地址，我們需要進入一個正在運行的容器並用下面的命令檢查ip地址。首先，我們運行一個新的容器並進入其中。如果你已經有一個正在運行的容器，你可以跳過這個步驟。</p><pre><code># docker run -it ubuntu
</code></pre><p>現在，我們可以運行ip a來得到容器的ip地址了。</p><pre><code># ip a
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-container-ip.png" alt="Docker Container IP"></p><h3 id="_3-映射暴露的端口" tabindex="-1">3. 映射暴露的端口 <a class="header-anchor" href="#_3-映射暴露的端口" aria-label="Permalink to “3. 映射暴露的端口”">​</a></h3><p>要映射配置在Dockerfile的暴露端口到宿主機的高位端口，我們只需用下面帶上-P標誌的命令。這會打開docker容器的隨機端口並映射到Dockerfile中定義的端口。下面是使用-P來打開/暴露定義的端口的例子。</p><pre><code># docker run -itd -P httpd
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/mapping-expose-port.png" alt="Mapping Expose Port"></p><p>上面的命令會映射容器的端口到 httpd 容器的 Dockerfile 中定義的80端口上。我們用下面的命令來查看正在運行的容器暴露的端口。</p><pre><code># docker ps
</code></pre><p>並且可以用下面的curl命令來檢查。</p><pre><code># curl http://localhost:49153
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/curl-exposed-port-e1431034586219.png" alt="Curl Exposed Port"></p><h3 id="_4-映射到特定的端口上" tabindex="-1">4. 映射到特定的端口上 <a class="header-anchor" href="#_4-映射到特定的端口上" aria-label="Permalink to “4. 映射到特定的端口上”">​</a></h3><p>我們也可以映射暴露端口或者docker容器端口到我們指定的端口上。要實現這個，我們用-p標誌來定義我們所需的端口。這裏是我們的一個例子。</p><pre><code># docker run -itd -p 8080:80 httpd
</code></pre><p>上面的命令會映射（宿主機的）8080端口到（容器的）80上。我們可以運行curl來檢查這點。</p><pre><code># curl http://localhost:8080
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/mapping-specific-port.png" alt="Mapping Specific Port"></p><h3 id="_5-創建自己的網橋" tabindex="-1">5. 創建自己的網橋 <a class="header-anchor" href="#_5-創建自己的網橋" aria-label="Permalink to “5. 創建自己的網橋”">​</a></h3><p>要給容器創建一個自定義的IP地址，在本篇中我們會創建一個名為br0的新網橋。要分配需要的ip地址，我們需要在運行docker的宿主機中運行下面的命令。</p><pre><code># stop docker.io
# ip link add br0 type bridge
# ip addr add 172.30.1.1/20 dev br0
# ip link set br0 up
# docker -d -b br0
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/creating-bridge-interface.png" alt="Creating Bridge Interface"></p><p>創建完docker網橋之後，我們要讓docker的守護進程知道它。</p><pre><code># echo &#39;DOCKER_OPTS=&quot;-b=br0&quot;&#39; &gt;&gt; /etc/default/docker
# service docker.io start
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/adding-interface-to-docker.png" alt="Adding Interface to Docker"></p><p>到這裏，橋接後的接口將會分配給容器在橋接子網內的新ip地址。</p><h3 id="_6-鏈接到另外一個容器上" tabindex="-1">6. 鏈接到另外一個容器上 <a class="header-anchor" href="#_6-鏈接到另外一個容器上" aria-label="Permalink to “6. 鏈接到另外一個容器上”">​</a></h3><p>我們可以用Docker將一個容器連接到另外一個上。我們可以在不同的容器上運行不同的程序，並且相互連接或鏈接。鏈接允許容器間相互連接並從一個容器上安全地傳輸信息給另一個容器。要做到這個，我們可以使用--link標誌。首先，我們使用--name標誌來標示training/postgres鏡像。</p><pre><code># docker run -d --name db training/postgres
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/running-db-container.png" alt="Running db Container"></p><p>完成之後，我們將容器db與training/webapp鏈接來形成新的叫web的容器。</p><pre><code># docker run -d -P --name web --link db:db training/webapp python app.py
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/linking-two-containers.png" alt="linking two containers"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>Docker網絡很神奇也好玩，我們可以對docker容器做很多事情。我們可以把玩這些簡單而基礎的docker網絡命令。docker的網絡是非常先進的，我們可以用它做很多事情。</p><p>如果你有任何的問題、建議、反饋請在下面的評論欄寫下來以便於我們我們可以提升或者更新文章的內容。謝謝！ 玩得開心！😃</p><hr>`,47)),p("p",null,[e[1]||(e[1]=o("via: ",-1)),t(r,{href:"http://linoxide.com/linux-how-to/networking-commands-docker-containers/"},{default:n(()=>[...e[0]||(e[0]=[o("http://linoxide.com/linux-how-to/networking-commands-docker-containers/",-1)])]),_:1})]),p("p",null,[e[5]||(e[5]=o("作者：",-1)),t(r,{href:"http://linoxide.com/author/arunp/"},{default:n(()=>[...e[2]||(e[2]=[o("Arun Pyasi",-1)])]),_:1}),e[6]||(e[6]=o(" 譯者：",-1)),t(r,{href:"https://github.com/geekpi"},{default:n(()=>[...e[3]||(e[3]=[o("geekpi",-1)])]),_:1}),e[7]||(e[7]=o(" 校對：",-1)),t(r,{href:"https://github.com/wxy"},{default:n(()=>[...e[4]||(e[4]=[o("wxy",-1)])]),_:1})]),p("p",null,[e[10]||(e[10]=o("本文由 ",-1)),t(r,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[8]||(e[8]=[o("LCTT",-1)])]),_:1}),e[11]||(e[11]=o(" 原創翻譯，",-1)),t(r,{href:"https://linux.cn/"},{default:n(()=>[...e[9]||(e[9]=[o("Linux中國",-1)])]),_:1}),e[12]||(e[12]=o(" 榮譽推出",-1))])])}const w=i(s,[["render",k]]);export{D as __pageData,w as default};
